using HakutaiKagami.Core.Messaging;
namespace HakutaiKagami.Core.Contracts;
public enum RemoteMilitaryAction { Issue,Resend,Accept }
public enum RemoteMilitaryKind { Offer,Receipt,FailureNotice }
public sealed record RemoteMilitaryInput(EntityId Id,RemoteMilitaryAction Action,EntityId Case,EntityId? Address=null,long MeetAt=0,string? Original=null);
public sealed record RemoteMilitaryEntry(RemoteMilitaryInput Input,long At,long Revision,string Paper);
public sealed record RemoteMilitaryPaper(string Id,RemoteMilitaryKind Kind,EntityId Case,EntityId Sender,EntityId Recipient,EntityId Address,long MeetAt,long Until,long At,long Revision,ActiveMilitaryAgreement Signature,string Root,string? Related,string? CopyOf,long? ObservedAt,string? Evidence);
public sealed record RemoteMilitaryState(int Schema,string Policy,RemoteMilitaryEntry[] Entries,RemoteMilitaryPaper[] Papers,FactionNoticeOpening[] Openings,FactionNoticeOpening[] FailureOpenings);
public static partial class NewGameMilitary
{
    public const string RemoteSuccessionContract="signed-fixed-site-appointment-military-offer-personal-acceptance-v1",RemoteSuccessionKind="military-command-succession";
    static readonly RemoteMilitaryState EmptyRemote=new(1,RemoteSuccessionContract,[],[],[],[]);
    static RemoteMilitaryState Remote(ContractWorld w)=>w.NewMilitary?.RemoteSuccession??EmptyRemote;
    static RemoteMilitaryPaper[] RemotePapers(ContractWorld w,long at,long rev)=>Remote(w).Papers.Where(p=>Before(p.At,p.Revision,at,rev)).ToArray();
    static RemoteMilitaryPaper RemoteRoot(ContractWorld w,RemoteMilitaryPaper p)=>Remote(w).Papers.Single(q=>q.Id==p.Root&&q.Kind==RemoteMilitaryKind.Offer&&q.CopyOf==null);
    static string RemoteId(EntityId id)=>"message:military-succession/"+Hash(id.Value);
    public static bool RemoteMilitaryIdUsed(ContractWorld w,EntityId id)=>LedgerStates(w).Any(s=>s.RemoteSuccession?.Entries.Any(e=>e.Input.Id==id)==true);
    static bool RemoteOpened(ContractWorld w,string id,EntityId actor,long at,long rev)=>Remote(w).Openings.Any(o=>o.Message==id&&o.Actor==actor&&Before(o.At,o.Revision,at,rev));
    static MessageEnvelope? RemoteFailure(ContractWorld w,RemoteMilitaryPaper p,long at,long rev)=>w.Messaging.Messages.FirstOrDefault(m=>m.Kind=="delivery-failure"&&m.RecipientId==p.Sender.Value&&w.Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id)&&Remote(w).FailureOpenings.Any(o=>o.Message==m.Id&&o.Actor==p.Sender&&Before(o.At,o.Revision,at,rev)));
    static bool RemoteFailureKnown(ContractWorld w,RemoteMilitaryPaper p,long at,long rev)=>p.Sender==w.PlayerControl?RemoteFailure(w,p,at,rev)!=null:RemotePapers(w,at,rev).Any(q=>q.Kind==RemoteMilitaryKind.FailureNotice&&q.Related==p.Id&&RemoteOpened(w,q.Id,w.PlayerControl,at,rev));
    static ActiveMilitaryAgreement RemoteAgreement(ContractWorld w,RemoteMilitaryInput i,long at,long rev){
        long before=rev-1;Need(i.Action==RemoteMilitaryAction.Accept&&i.Address==null&&i.MeetAt==0&&i.Original!=null,"本人が開封した引継ぎ書状を指定してください");var p=RemotePapers(w,at,before).Single(q=>q.Id==i.Original);var root=RemoteRoot(w,p);var s=w.NewMilitary!;
        Need(p.Kind==RemoteMilitaryKind.Offer&&p.Recipient==w.PlayerControl&&p.Case==i.Case&&RemoteOpened(w,p.Id,w.PlayerControl,at,before)&&at<=p.Until&&!ActiveAt(w,at,before).Any(e=>e.Input.Id==i.Id)&&!Remote(w).Entries.Any(e=>e.Input.Action==RemoteMilitaryAction.Accept&&e.Input.Id!=i.Id&&RemotePapers(w,at,before).Any(q=>q.Id==e.Input.Original&&q.Root==root.Id)&&Before(e.At,e.Revision,at,before)),"期限内の本人開封原本を、一度だけ承諾してください");
        Need(CaseStart(w,at,before)?.Input.Id==i.Case&&s.Terms.Army==p.Signature.Army&&s.Terms.Owner==p.Signature.Owner&&s.Terms.Site==p.Signature.Site&&CasePrincipal(w,at,before)==p.Signature.Previous&&HouseSuccession.Head(w,s.Terms.Owner,at,before)==p.Sender&&CustodyAt(w,at,before)&&!Returning(w,at,before)&&!CombatActive(w)&&!RoutActive(w)&&MemberOfGarrisonHouse(w,w.PlayerControl,s.Terms.Owner,at,before),"同じ軍務・軍・現在の締結権限を確認できません");
        Need(FactionStances.ResolveAuthority(w,p.Sender,s.Terms.Owner,at,before)!=null,"書状の署名権限を確認できません");
        return p.Signature with{Input=new(i.Id,i.Case),At=at,Revision=rev};
    }
    static RemoteMilitaryPaper MakeRemote(ContractWorld w,RemoteMilitaryInput i,long at,long rev){
        long before=rev-1;Need(HouseSuccession.Enabled(w)&&EntityId.IsValid(i.Id.Value)&&Enum.IsDefined(i.Action)&&w.NewMilitary!=null,"軍務引継ぎ書状の入力が不正です");
        if(i.Action==RemoteMilitaryAction.Issue){var signature=PrepareActive(w,new(i.Id,i.Case),at,rev);Need(i.Original==null&&i.Address is {}&&BranchRoutes.GraphNodes(w).Any(n=>RegionalCampaign.Site(n.Id)==i.Address)&&i.MeetAt>=at+1&&i.MeetAt<=at+7*86400&&!RemotePapers(w,at,before).Any(p=>p.Kind==RemoteMilitaryKind.Offer&&p.CopyOf==null&&p.Case==i.Case&&p.Until>=at),"固定拠点と7日以内の待合日時を指定し、先の書状を処理してください");signature=signature with{Source=signature.Source with{Contract=RemoteSuccessionContract}};var id=RemoteId(i.Id);return new(id,RemoteMilitaryKind.Offer,i.Case,signature.Principal,w.PlayerControl,i.Address!.Value,i.MeetAt,checked(i.MeetAt+86400),at,rev,signature,id,null,null,null,null);}
        if(i.Action==RemoteMilitaryAction.Accept){var agreement=RemoteAgreement(w,i,at,rev);var p=RemotePapers(w,at,before).Single(p=>p.Id==i.Original);var root=RemoteRoot(w,p);return new(RemoteId(i.Id),RemoteMilitaryKind.Receipt,i.Case,w.PlayerControl,p.Sender,root.Signature.Site,at+1,root.Until,at,rev,root.Signature,root.Id,p.Id,null,at,p.Id);}
        Need(i.Address==null&&i.MeetAt==0&&i.Original!=null,"既知不達の原本を指定してください");var old=RemotePapers(w,at,before).Single(p=>p.Id==i.Original);var origin=RemoteRoot(w,old);Need(old.Case==i.Case&&old.Kind is RemoteMilitaryKind.Offer or RemoteMilitaryKind.Receipt&&RemoteFailureKnown(w,old,at,before),"本人が実際に知った不達だけ再送できます");
        var family=RemotePapers(w,at,before).Where(p=>p.Kind==old.Kind&&p.Root==old.Root&&p.Related==old.Related).ToArray();Need(family.Length<3,"同じ原本の写しは三通までです");
        if(old.Kind==RemoteMilitaryKind.Offer){Need(at<=origin.Until&&!Remote(w).Entries.Any(e=>e.Input.Action==RemoteMilitaryAction.Accept&&RemotePapers(w,at,before).Any(p=>p.Id==e.Input.Original&&p.Root==origin.Id)&&Before(e.At,e.Revision,at,before)),"承諾済み/期限切れの書状は再送しません");var current=PrepareActive(w,new(i.Id,i.Case),at,rev);Need(current.Principal==old.Sender,"元の署名者を再確認してください");}else Need(old.Sender==w.PlayerControl,"本人の返書を指定してください");
        return old with{Id=RemoteId(i.Id),At=at,Revision=rev,CopyOf=old.Id};
    }
    static MessageEnvelope RemoteEnvelope(RemoteMilitaryPaper p)=>new(p.Id,p.Case.Value,RemoteSuccessionKind,p.Sender.Value,p.Recipient.Value,Text(p),p.Address.Value,p.At,p.Kind==RemoteMilitaryKind.Offer?p.Until:null);
    static void SendRemote(ContractWorld w,RemoteMilitaryPaper p){w.NewMilitary=w.NewMilitary! with{RemoteSuccession=Remote(w) with{Papers=[..Remote(w).Papers,p]}};MessageFlow.Send(w.Messaging,RemoteEnvelope(p),p.At,1);w.SealedMessages=[..w.SealedMessages,new(p.Id)];}
    internal static void ApplyRemote(ContractWorld w,RemoteMilitaryInput i){var p=MakeRemote(w,i,w.ElapsedSeconds,w.CommitSequence);if(i.Action==RemoteMilitaryAction.Accept){var e=RemoteAgreement(w,i,w.ElapsedSeconds,w.CommitSequence);w.NewMilitary=w.NewMilitary! with{ActiveSuccession=new(ActiveSuccessionContract,[..w.NewMilitary.ActiveSuccession?.Entries??[],e])};}w.NewMilitary=w.NewMilitary! with{RemoteSuccession=Remote(w) with{Entries=[..Remote(w).Entries,new(i,w.ElapsedSeconds,w.CommitSequence,p.Id)]}};SendRemote(w,p);SyncAuthority(w);}
    static void RecordRemoteOpeningLedger(ContractWorld w,EntityId actor,string id){
        var p=Remote(w).Papers.SingleOrDefault(p=>p.Id==id&&p.Recipient==actor);if(p!=null){if(!Remote(w).Openings.Any(o=>o.Message==id)){Need(MessageFlow.Knows(w.Messaging,id,actor.Value),"本人開封ではありません");w.NewMilitary=w.NewMilitary! with{RemoteSuccession=Remote(w) with{Openings=[..Remote(w).Openings,new(id,actor,w.ElapsedSeconds,w.CommitSequence)]}};}return;}
        if(w.NewMilitary?.RemoteSuccession==null||Remote(w).FailureOpenings.Any(o=>o.Message==id))return;var f=w.Messaging.Messages.SingleOrDefault(m=>m.Id==id&&m.Kind=="delivery-failure"&&m.RecipientId==actor.Value&&Remote(w).Papers.Any(p=>w.Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id)));if(f!=null){Need(MessageFlow.Knows(w.Messaging,id,actor.Value),"不達を本人が知っていません");w.NewMilitary=w.NewMilitary! with{RemoteSuccession=Remote(w) with{FailureOpenings=[..Remote(w).FailureOpenings,new(id,actor,w.ElapsedSeconds,w.CommitSequence)]}};}
    }
    internal static void RecordRemoteOpening(ContractWorld w,EntityId actor,string id)=>ForEachLedger(w,c=>RecordRemoteOpeningLedger(c,actor,id));
    static void UpdateRemoteLedger(ContractWorld w){if(w.NewMilitary?.RemoteSuccession==null)return;foreach(var m in w.Messaging.Messages.Where(m=>m.RecipientId!=w.PlayerControl.Value&&(Remote(w).Papers.Any(p=>p.Id==m.Id)||m.Kind=="delivery-failure"&&Remote(w).Papers.Any(p=>w.Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id)))).ToArray())if(w.Messaging.Attempts.Any(a=>a.MessageId==m.Id&&a.ReceiverId==m.RecipientId&&a.Status==AttemptStatus.Delivered)){if(!MessageFlow.Knows(w.Messaging,m.Id,m.RecipientId))w.Messaging.Knowledge=[..w.Messaging.Knowledge,new(m.Id,m.RecipientId,w.ElapsedSeconds,m.Id)];RecordRemoteOpeningLedger(w,new(m.RecipientId),m.Id);}}
    internal static void UpdateRemote(ContractWorld w){ForEachLedger(w,UpdateRemoteLedger);var ids=LedgerStates(w).SelectMany(s=>s.RemoteSuccession?.Papers??[]).Select(p=>p.Id).ToHashSet();foreach(var m in w.Messaging.Messages.Where(m=>m.Kind=="delivery-failure"&&m.RecipientId==w.PlayerControl.Value&&w.Messaging.Attempts.Any(a=>a.Id==m.Body&&ids.Contains(a.MessageId))))if(!w.SealedMessages.Contains(new(m.Id)))w.SealedMessages=[..w.SealedMessages,new(m.Id)];}
    static RemoteMilitaryPaper? NextRemote(ContractWorld w){long at=w.ElapsedSeconds,rev=w.CommitSequence+1;var ps=RemotePapers(w,at,rev-1);foreach(var p in ps.Where(p=>p.Kind==RemoteMilitaryKind.Offer&&p.Sender!=w.PlayerControl)){var failure=RemoteFailure(w,p,at,rev-1);if(failure==null||ps.Any(q=>q.Kind==RemoteMilitaryKind.FailureNotice&&q.Evidence==failure.Id))continue;var root=RemoteRoot(w,p);return new("message:military-succession-failure/"+Hash(failure.Id),RemoteMilitaryKind.FailureNotice,p.Case,p.Sender,root.Recipient,root.Signature.Site,at+1,root.Until,at,rev,root.Signature,root.Id,p.Id,null,MessageFlow.LearnedAt(w.Messaging,failure.Id,p.Sender.Value),failure.Id);}
        foreach(var p in ps.Where(p=>p.Kind==RemoteMilitaryKind.FailureNotice&&p.Sender!=w.PlayerControl)){var family=ps.Where(q=>q.Kind==p.Kind&&q.Root==p.Root&&q.Related==p.Related&&q.Evidence==p.Evidence).ToArray();if(family.Length>=3||family[^1].Id!=p.Id||RemoteFailure(w,p,at,rev-1)==null)continue;return p with{Id="message:military-succession-report-retry/"+Hash(p.Id),At=at,Revision=rev,CopyOf=p.Id};}return null;}
    internal static void AutomaticRemote(ContractWorld w,EntityId army){var ledger=LedgerStates(w).Single(s=>s.Terms.Army==army);var c=LedgerContext(w,ledger);c.CommitSequence--;var p=NextRemote(c);Need(p!=null,"自動返報の根拠がありません");c.CommitSequence++;SendRemote(c,p);w.SealedMessages=c.SealedMessages;w.Messaging=c.Messaging;if(w.NewMilitary!.Terms.Army==army)w.NewMilitary=c.NewMilitary;else w.OtherMilitaryLedgers=w.OtherMilitaryLedgers!.Select(s=>s.Terms.Army==army?c.NewMilitary!:s).ToArray();}
    internal static void TakeRemoteTurns(WorldSession session){for(int n=0;n<32;n++){var w=session.DiagnosticSnapshot();var ledger=LedgerStates(w).FirstOrDefault(s=>NextRemote(LedgerContext(w,s))!=null);if(ledger==null)return;session.AutoRemoteMilitary(ledger.Terms.Army);}}
    static RemoteMilitaryState? RemoteBefore(RemoteMilitaryState? s,long at,long rev)=>s==null||!s.Entries.Any(e=>Before(e.At,e.Revision,at,rev))?null:s with{Entries=s.Entries.Where(e=>Before(e.At,e.Revision,at,rev)).ToArray(),Papers=s.Papers.Where(p=>Before(p.At,p.Revision,at,rev)).ToArray(),Openings=s.Openings.Where(o=>Before(o.At,o.Revision,at,rev)).ToArray(),FailureOpenings=s.FailureOpenings.Where(o=>Before(o.At,o.Revision,at,rev)).ToArray()};
    internal static IEnumerable<(long At,long Revision)> RemoteInputs(ContractWorld w)=>LedgerStates(w).SelectMany(s=>(s.RemoteSuccession?.Entries??[]).Select(e=>(e.At,e.Revision)).Concat((s.RemoteSuccession?.Openings??[]).Concat(s.RemoteSuccession?.FailureOpenings??[]).Where(o=>o.Actor==w.PlayerControl).Select(o=>(o.At,o.Revision))));
    public static string? RemoteAddress(ContractWorld w,MessageEnvelope m)=>LedgerStates(w).SelectMany(s=>s.RemoteSuccession?.Papers??[]).SingleOrDefault(p=>p.Id==m.Id) is {} p?NewGameWorld.Node(p.Address.Value):null;
    internal static long? RemoteAppointment(ContractWorld w,MessageEnvelope m)=>LedgerStates(w).SelectMany(s=>s.RemoteSuccession?.Papers??[]).SingleOrDefault(p=>p.Id==m.Id)?.MeetAt;
    internal static bool RemotePendingAllows(ContractWorld w)=>RemotePapers(w,w.ElapsedSeconds,w.CommitSequence).Any(p=>p.Kind==RemoteMilitaryKind.Offer&&p.Recipient==w.PlayerControl&&p.Case==CaseStart(w)?.Input.Id&&p.Signature.Previous==CasePrincipal(w)&&p.Signature.Army==w.NewMilitary?.Terms.Army&&p.Sender==HouseSuccession.Head(w,p.Signature.Owner)&&w.ElapsedSeconds<=p.Until&&MemberOfGarrisonHouse(w,w.PlayerControl,p.Signature.Owner,w.ElapsedSeconds,w.CommitSequence));
    public static bool CanSendRemote(ContractWorld w,RemoteMilitaryInput i){try{MakeRemote(w,i,w.ElapsedSeconds,w.CommitSequence+1);return true;}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException){return false;}}
    static ActiveMilitaryAgreement ExpectedRemoteAgreement(ContractWorld w,ActiveMilitaryAgreement e){var i=Remote(w).Entries.Single(q=>q.Input.Id==e.Input.Id&&q.Input.Action==RemoteMilitaryAction.Accept&&q.At==e.At&&q.Revision==e.Revision).Input;var c=BeforeState(w,e.At,e.Revision-1);c.CommitSequence=e.Revision;return RemoteAgreement(c,i,e.At,e.Revision);}
    static void ValidateRemote(ContractWorld w){var s=w.NewMilitary?.RemoteSuccession;if(s==null)return;Need(s.Schema==1&&s.Policy==RemoteSuccessionContract&&s.Entries!=null&&s.Papers!=null&&s.Openings!=null&&s.FailureOpenings!=null&&s.Entries.All(e=>e!=null&&e.Input!=null)&&s.Papers.All(p=>p!=null&&p.Signature!=null)&&s.Entries.Select(e=>e.Input.Id).Distinct().Count()==s.Entries.Length&&s.Papers.Select(p=>p.Id).Distinct().Count()==s.Papers.Length&&s.Openings.Select(o=>o.Message).Distinct().Count()==s.Openings.Length,"遠隔軍務原本の版・項目が不正です");long rev=0;foreach(var e in s.Entries){Need(e.Revision>rev&&e.Revision<=w.CommitSequence&&e.At<=w.ElapsedSeconds&&!FactionStances.OtherIdUsed(w,e.Input.Id,includeActiveMilitary:false,includeRemoteMilitary:false)&&!FactionStances.OwnIdUsed(w,e.Input.Id),"遠隔軍務のID・順序が不正です");var c=BeforeState(w,e.At,e.Revision-1);c.CommitSequence=e.Revision;Need(MakeRemote(c,e.Input,e.At,e.Revision)==s.Papers.Single(p=>p.Id==e.Paper),"遠隔軍務の依頼・署名・宛先が一致しません");if(e.Input.Action==RemoteMilitaryAction.Accept)Need(w.NewMilitary!.ActiveSuccession?.Entries.Contains(RemoteAgreement(c,e.Input,e.At,e.Revision))==true,"承諾と新しい指揮原本が一致しません");rev=e.Revision;}
        foreach(var p in s.Papers){Need(p.Revision>0&&p.Revision<=w.CommitSequence&&p.At<=w.ElapsedSeconds&&w.Messaging.Messages.Contains(RemoteEnvelope(p))&&w.SealedMessages.Contains(new(p.Id)),"引継ぎ封書の原文が違います");if(!s.Entries.Any(e=>e.Paper==p.Id)){var c=BeforeState(w,p.At,p.Revision-1);Need(NextRemote(c)==p,"返報の物理不達・認識・写しが違います");}foreach(var a in w.Messaging.Attempts.Where(a=>a.MessageId==p.Id)){var c=w.Couriers!.Missions.Single(c=>c.Attempt==a.Id);Need(c.Destination==NewGameWorld.Node(p.Address.Value)&&c.Appointment==p.MeetAt,"宛先/待合時刻を追尾へすり替えています");}}
        foreach(var o in s.Openings){var p=s.Papers.Single(p=>p.Id==o.Message);Need(o.Actor==p.Recipient&&o.Revision>p.Revision&&o.Revision<=w.CommitSequence&&o.At<=w.ElapsedSeconds&&MessageFlow.LearnedAt(w.Messaging,p.Id,o.Actor.Value)==o.At&&w.Messaging.Attempts.Any(a=>a.MessageId==p.Id&&a.ReceiverId==o.Actor.Value&&a.Status==AttemptStatus.Delivered&&a.FinishedAt<=o.At),"本人の物理開封ではありません");}
        Need(s.FailureOpenings.Select(o=>o.Message).Distinct().Count()==s.FailureOpenings.Length,"不達認識が重複しています");foreach(var o in s.FailureOpenings){var f=w.Messaging.Messages.Single(m=>m.Id==o.Message);Need(f.Kind=="delivery-failure"&&f.RecipientId==o.Actor.Value&&o.At<=w.ElapsedSeconds&&o.Revision>0&&o.Revision<=w.CommitSequence&&MessageFlow.LearnedAt(w.Messaging,f.Id,o.Actor.Value)<=o.At&&s.Papers.Any(p=>w.Messaging.Attempts.Any(a=>a.Id==f.Body&&a.MessageId==p.Id))&&w.Messaging.Attempts.Any(a=>a.MessageId==f.Id&&a.ReceiverId==o.Actor.Value&&a.Status==AttemptStatus.Delivered&&a.FinishedAt<=o.At),"不達の本人認識ではありません");}
