}
public sealed partial class WorldSession
{
    internal void AutoRemoteMilitary(EntityId army){lock(gate)Change(w=>NewGameMilitary.AutomaticRemote(w,army));}
    public CommandResult SendRemoteMilitary(RemoteMilitaryInput i,EntityId actor,long revision){lock(gate){if(actor!=state.PlayerControl)return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,"本人の軍務書状操作ではありません");var old=NewGameMilitary.LedgerStates(state).SelectMany(s=>s.RemoteSuccession?.Entries??[]).SingleOrDefault(e=>e.Input.Id==i.Id);if(old!=null)return new(old.Input==i?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"受付済みです");if(FactionStances.OtherIdUsed(state,i.Id)||FactionStances.OwnIdUsed(state,i.Id))return new(ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"別の原本です");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");try{Change(w=>NewGameMilitary.ApplyRemote(w,i));NewGameMilitary.TakeRemoteTurns(this);return new(ResultCode.Accepted,i.Id,state.CommitSequence,"引継ぎ書状を処理しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
